import {installTagCoverDraft} from '../frontend/dist/tag-editor-cover-draft.js';
const entries=[{file:'DEMO/secret-track-one.flac'},{file:'DEMO/secret-track-two.mp3'}];
const c=document.createElement('canvas');c.width=40;c.height=20;c.getContext('2d').fillRect(0,0,40,20);const image=c.toDataURL('image/jpeg');
const editor=installTagCoverDraft({getAlbum:()=>({id:'11111111-1111-4111-8111-111111111111',entries}),getSelectedFiles:()=>[entries[0].file],api:async()=>({state:'EMBEDDED_COVER_INSPECTED',front_covers:[{sha256:'a'.repeat(64)}],preview_data_url:image,other_cover_count:0})});
const q=s=>document.querySelector(s);q('#test').onclick=async()=>{const results=[];const check=(n,ok)=>{if(!ok)throw Error(n);results.push(n)};try{editor.open();check('No file dropdown or file names',!q('#tagCoverDialog select')&&!q('#tagCoverDialog').textContent.includes('secret-track'));check('Album count defaults to two',q('#tagCoverFiles').textContent.includes('전체 2곡'));q('[data-cover-inspect]').click();for(let i=0;i<40&&q('[data-cover-inspect]').disabled;i++)await new Promise(r=>setTimeout(r,10));check('Current embedded summary has no SHA/file names',!q('.tag-cover-current').textContent.includes('SHA256')&&!q('.tag-cover-current').textContent.includes('secret-track'));const box=q('.tag-cover-current').getBoundingClientRect();check('Current square box',Math.abs(box.width-box.height)<2);check('Preview keeps contain',getComputedStyle(q('.tag-cover-current img')).objectFit==='contain');q('[data-cover-scope="__selected__"]').click();check('Existing track selection is scope',q('#tagCoverFiles').textContent.includes('선택 1곡'));check('Save defaults OFF',q('[data-cover-save]').disabled);q('#result').textContent=JSON.stringify({pass:results.length,results,actual_nas_calls:0,operating_writes:0},null,2);editor.close();}catch(e){q('#result').textContent=JSON.stringify({results,error:e.message});editor.close();}};
